// Every person with the "approve" right (and the owner) gets an email with Approve / Reject buttons; the in-app banner still works.
function apSecret_() {
  const p = PropertiesService.getScriptProperties(); let k = p.getProperty('AP_SECRET');
  if (!k) { k = Utilities.getUuid() + Utilities.getUuid(); p.setProperty('AP_SECRET', k); }
  return k;
}
function apKey_(id, name) {
  return Utilities.computeHmacSha256Signature(id + '|' + name, apSecret_()).map(b => ((b + 256) % 256).toString(16).padStart(2, '0')).join('').slice(0, 24);
}
function apApprovers_(except) {
  const out = [], owner = String(setting_('Owner email', 'nutzyfoods@gmail.com') || '').trim();
  if (owner) out.push({ name: OWNER_NAME, email: owner });
  userRows_().forEach(x => {
    const u = userObj_(x.r), em = s_(x.r[UC['Email']]);
    if (u.active && em && u.name !== except && (u.role === 'Owner' || u.rights.indexOf('approve') >= 0)) out.push({ name: u.name, email: em });
  });
