  const base = ScriptApp.getService().getUrl() + '?ap=' + encodeURIComponent(id) + '&n=' + encodeURIComponent(name) + '&k=' + s_(q.k);
  return page('Approve this discount?', info + '<div style="display:flex;gap:10px;margin-top:16px"><a href="' + base + '&go=no" style="flex:1;text-align:center;padding:14px;border:1px solid #c0392b;color:#c0392b;border-radius:8px;text-decoration:none;font-weight:bold">Reject</a>' +
    '<a href="' + base + '&go=yes" style="flex:1;text-align:center;padding:14px;background:#C9A24A;color:#1F2A44;border-radius:8px;text-decoration:none;font-weight:bold">Approve ' + n_(r[8]) + '%</a></div>' +
    '<p style="color:#888;font-size:12px;margin-top:14px">Approving as ' + esc(name) + '.</p>');
}

