      if ([p.cash, p.upi, p.card].some(v => v < 0)) throw new Error('Amounts cannot be negative.');
      const sum = round2_(p.cash + p.upi + p.card);
      if (Math.abs(sum - received) > 0.009) throw new Error('Cash + UPI + Card = ₹' + sum + ' but ₹' + received + ' was received' + (sx ? ' (bill ₹' + total + ' less short ₹' + sx.short + ')' : '') + '.');
    } else p[mode.toLowerCase()] = received;
    const old = payText_(b.pay);
    // full amounts (as if fully paid): the short sits on a method that was used
    const full = Object.assign({ mode: mode }, p);
    if (sx) {
      let k = sx.mode.toLowerCase();
      if (!(p[k] > 0) && mode !== 'Split') k = mode.toLowerCase();
      if (!(p[k] > 0) && mode === 'Split') k = ['cash', 'upi', 'card'].sort((a, c) => p[c] - p[a])[0];
      full[k] = round2_(full[k] + sx.short); sx.mode = k === 'upi' ? 'UPI' : k.charAt(0).toUpperCase() + k.slice(1);
      const x = shRows_(); x.rows.forEach((q, i) => { if (s_(q[0]) === s_(d.no) && s_(q[12]) === 'Active') x.sh.getRange(i + 2, 8).setValue(sx.mode); });
    }
    b.payFull = full;
    b.payChanges = (b.payChanges || []).concat([{ from: old, to: payText_(Object.assign({ mode: mode }, p)), reason: reason, by: user.name, at: new Date().toISOString() }]);
    r[BC['Payment']] = mode;
    applyShortToBill_(row, r, b, sx);
    const ph = btab2_(PC_TAB, PC_H);
    ph.getRange(ph.getLastRow() + 1, 1, 1, PC_H.length).setValues([[s_(d.no), ymd_(r[BC['Date']]), s_(r[BC['Location']]), total, old, payText_(Object.assign({ mode: mode }, p)), reason, user.name, new Date()]]);
  } finally { lock.releaseLock(); }
  return { bill: getBillByNo_(d.no) };
}

